selector_to_html = {"a[href=\"#flagtree-0-7-0-release\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTree 0.7.0 Release<a class=\"headerlink\" href=\"#flagtree-0-7-0-release\" title=\"Link to this heading\">#</a></h1>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-spacemit.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab SpacemiT\uff08\u8fdb\u8fed\u65f6\u7a7a\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/spacemit/\">spacemit</a>3.6<a class=\"headerlink\" href=\"#spacemit-spacemit3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (x64 emulation environment)<a class=\"headerlink\" href=\"#use-the-image-x64-emulation-environment\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-iluvatar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ILUVATAR\uff08\u5929\u6570\u667a\u82af\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/iluvatar/\">iluvatar</a>3.6<a class=\"headerlink\" href=\"#iluvatar-iluvatar3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (BI-V150)<a class=\"headerlink\" href=\"#use-the-image-bi-v150\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-amd.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab AMD <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/amd/\">amd</a><a class=\"headerlink\" href=\"#amd-amd\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/flagtree-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Enable FlagTree CPU on Arm64<a class=\"headerlink\" href=\"#enable-flagtree-cpu-on-arm64\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/flagtree-cpu/tree/triton_v3.7.x\">FlagTree CPU</a> provides a CPU backend for Triton, allowing kernels written with Triton\u2019s Python API to compile and run on CPUs. Its compiler lowers Triton kernels through MLIR/LLVM into native CPU code, while its runtime handles CPU target selection, kernel launches, and compilation caching. This guide covers the Triton 3.7.2 implementation on Linux Arm64 and validates it with a vector-add kernel and FlagGems W4A8 operator tests.</p><p>Build and validate the Triton 3.7.2 CPU backend using the scripts in <a class=\"reference external\" href=\"https://github.com/flagos-ai/community/tree/main/fep/sig-edge/scripts/flagtree-cpu37\">flagos-ai/community</a>. Follow these steps in the same shell.</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-sunrise.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Sunrise\uff08\u66e6\u671b\u82af\u79d1\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/sunrise/\">sunrise</a>3.6<a class=\"headerlink\" href=\"#sunrise-sunrise3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (S2)<a class=\"headerlink\" href=\"#use-the-image-s2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-ppu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab T-Head\uff08\u5e73\u5934\u54e5\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/ppu/\">ppu</a>3.6<a class=\"headerlink\" href=\"#t-head-ppu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (810E|890P)<a class=\"headerlink\" href=\"#use-the-image-810e-890p\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-tsingmicro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Tsingmicro\uff08\u6e05\u5fae\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tsingmicro/\">tsingmicro</a>3.6<a class=\"headerlink\" href=\"#tsingmicro-tsingmicro3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (TX81)<a class=\"headerlink\" href=\"#use-the-image-tx81\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-tileir.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA TileIR <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tileir/\">tileir</a>3.6<a class=\"headerlink\" href=\"#nvidia-tileir-tileir3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (Hopper/Blackwell)<a class=\"headerlink\" href=\"#use-the-image-hopper-blackwell\" title=\"Link to this heading\">#</a></h3><p>This image can also be used for the <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia</span></code> backend.</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-xpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab KLX <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/xpu/\">xpu</a>3.6<a class=\"headerlink\" href=\"#klx-xpu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (P800)<a class=\"headerlink\" href=\"#use-the-image-p800\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
